build.VisitAllChildren<SourceFile>(sf => {
    Console.WriteLine($"SourceFile: {sf.Name}");
});

// Try to find the content via SourceFilesArchive 
Console.WriteLine("\n=== Looking for file contents ===");
var archive = build.SourceFilesArchive;
if (archive != null) {
    foreach (var entry in archive.Children) {
        Console.WriteLine($"Archive entry: {entry.GetType().Name} - {entry}");
    }
}

// Get more details about the errors - find the actual source text
Console.WriteLine("\n=== DETAILED ERROR CONTEXT ===");
build.VisitAllChildren<Error>(e => {
    var project = e.GetNearestParent<Project>();
    Console.WriteLine($"\nProject: {project?.Name}");
    Console.WriteLine($"Error: {e.Code} - {e.Text}");
    Console.WriteLine($"File: {e.File}");
    Console.WriteLine($"Line: {e.LineNumber}, Col: {e.ColumnNumber}");
});

// Get project dependency info
Console.WriteLine("\n=== PROJECT REFERENCES ===");
build.VisitAllChildren<Project>(p => {
    Console.WriteLine($"\nProject: {p.Name}");
    p.VisitAllChildren<Item>(i => {
        if (i.Name == "ProjectReference" || i.Name == "PackageReference")
            Console.WriteLine($"  {i.Name}: {i.Text}");
    });
});
